   "solution":"Картина «у одних старая форма, у других новая при одной версии» имеет две типичные причины: старый файл приложения в кэше клиента и включённый на часть аудитории флаг функции. Разделяются они быстро: приватное окно и жёсткая перезагрузка. Если после этого форма новая — дело в кэше; если старая, а доля жалоб близка к доле выключенного флага — дело в эксперименте. Обращения делятся на две группы: первой даём инструкцию по обновлению, вторую передаём разработке с данными о доле и просьбой либо включить флаг шире, либо описать поведение в статусе.",
