   "answer":"Сначала stdout направляется в файл, затем stderr присоединяется к уже перенаправленному stdout — обе струи попадают в out.log. В обратном порядке stderr успел бы «прицепиться» к экрану.",
   "category":"Linux и системы",
   "common_confusion":"Пишут cmd 2>&1 > out.log и удивляются ошибкам на экране: порядок важен — сначала указывают файл для stdout, потом присоединяют stderr.",
   "definition_interview":"У процесса три стандартных потока: stdin (вход), stdout (вывод), stderr (ошибки). Перенаправляются независимо: > пишет stdout, 2> — stderr, 2>&1 объединяет их.",
   "definition_simple":"Два выхода каждой команды: обычный вывод и поток ошибок.",
