   "short_answer":"Сначала выравниваю условия: версия, браузер, роль, регион, данные, время события с часовым поясом. Прошу идентификатор запроса или точное время, чтобы найти его в логах — там видно, была ли ошибка на самом деле. Дальше пробую повторить под учётной записью с такими же правами, а не под своей. Если не воспроизводится, я пишу не «не воспроизводится», а что именно проверил и какие условия остались непроверенными.",
