   "short_answer":"Сначала сужаю окно: точное время с часовым поясом и идентификатор запроса или заказа. Ищу по идентификатору, а не по слову «ошибка» — так виден весь путь запроса через сервисы. Смотрю не одну строку, а контекст вокруг: что было до и после. Дальше сверяю уровни: если ERROR есть, а поведение нормальное, значит, эта ошибка не про клиента. И если записи нет вообще — это тоже ответ: запрос до нас не дошёл.",
