   "short_answer":"401 — запрос без действительной аутентификации: система не знает, кто вы. 403 — вы известны, но у вас нет прав на это действие. 404 — объекта или адреса нет, и иногда за этим скрывается ограничение прав. 502 значит, что шлюз получил некорректный ответ от сервиса за ним, то есть проблема внутри инфраструктуры, а не в запросе клиента.",
