   "short_answer":"Смотрю статус службы: работает ли она и не перезапускалась ли недавно. Дальше её журнал за последние минуты. Параллельно проверяю ресурсы: место на диске, память, нагрузку — переполненный диск и нехватка памяти выглядят как случайные ошибки. Если процесс жив, а ответов нет, проверяю, слушает ли он нужный порт и отвечает ли локально.",
