   "short_answer":"Читаю с реплики, если она есть. Всегда ставлю LIMIT и сначала смотрю план или количество строк, а не выгружаю всё. Пишу запрос по индексируемым полям — идентификатор, дата, — а не по подстроке в тексте. Любое изменение данных делаю только по согласованию, в транзакции и после SELECT тех же строк, чтобы видеть, что именно поменяется. Персональные данные из выборки в переписку не переношу.",
