   "short_answer":"Считаю перезапуск временной мерой и записываю время, когда он понадобился: периодичность сама по себе подсказка. Дальше смотрю, что изменилось перед первым случаем — выкат, конфигурация, рост данных. Формулирую одну гипотезу и проверяю её данными, не меняя ничего другого. Когда механизм найден, завожу задачу на устранение и описываю обходное решение в базе знаний, чтобы дежурный не искал заново.",
