   "short_answer":"Сравниваю время первого обращения со временем выката и включения флагов. Смотрю, у всех ли клиентов проблема или у доли, похожей на долю эксперимента. Проверяю версию у клиента и то, что он видит после сброса кэша. Если совпадений достаточно, иду к разработке с фактами: время, доля, шаги и предложение откатить или выключить флаг, пока идёт разбор.",
