   "estimated_minutes":25,
   "example":"Клиент присылает скриншот с полным номером карты. Правильная реакция: удалить вложение, сообщить клиенту, зафиксировать в тикете, что данные удалены, и продолжить разбор по идентификатору платежа.",
   "id":"lesson-ts-privacy",
