   "short_answer":"Не использую его. Удаляю сообщение или вложение из переписки, объясняю клиенту, что пароль не нужен и что его стоит сменить, и фиксирую в тикете, что данные удалены. Дальше продолжаю разбор законным путём: по идентификатору обращения, через доступ поддержки с ограниченными правами или с временным доступом по согласованной процедуре.",
