   "estimated_minutes":25,
   "example":"Пятнадцать обращений в месяц про экспорт отчёта решались одинаково. После статьи из семи строк первая линия закрывает их за три минуты, а задача на исправление причины ушла в бэклог с оценкой «15 обращений в месяц».",
