   "short_answer":"Пишу короткую статью по схеме: признаки, по которым узнать проблему; проверенные шаги решения; ограничения и что делать нельзя; ссылку на тикет и задачу разработке, если причина не устранена. Ставлю владельца и дату проверки. Ссылку кладу в тикет — так статья находится и видно, как часто она нужна. Если такое обращение повторяется, я иду не за третьей статьёй, а за задачей на устранение причины.",
