   "short_answer":"Говорю прямо и в первом предложении: быстрого решения нет, ориентировочный срок такой. Объясняю причину без жаргона и коротко. Обязательно даю обходной путь, если он есть, даже неудобный. Называю время следующего обновления и присылаю его, даже если новостей нет. Одно извинение в начале, дальше только факты — так у человека остаётся ощущение, что его вопросом занимаются, а не отделываются.",
