   "short_answer":"Называю конкретный случай, а не общие слова. Говорю, в чём была ошибка и как я её заметил. Дальше — что сделал сразу: сообщил клиенту и коллегам до того, как меня спросили, и исправил последствия. И заканчиваю тем, что изменилось после: чек-лист, проверка перед действием или правило в базе знаний. Такая история показывает, что ошибку я обнаруживаю и закрываю сам.",
